package controller; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.*; public class VendorLogoutServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse s)throws IOException{HttpSession x=r.getSession(false);if(x!=null){x.removeAttribute("vendorLoggedIn");x.removeAttribute("vendorId");x.removeAttribute("vendorName");x.removeAttribute("vendorEmail");if("VENDOR".equals(x.getAttribute("role")))x.removeAttribute("role");}s.sendRedirect(r.getContextPath()+"/vendorLogin.jsp");}}